  [14323] = { "Applica il ⟦Hunter's Mark=Marchio del Cacciatore⟧ al bersaglio, aumentando di $N1 la potenza d'attacco a distanza di tutti gli attaccanti contro quel bersaglio. Inoltre, il bersaglio di questa abilità resta sempre visibile al Cacciatore, anche se diventa furtivo o invisibile. Il bersaglio appare anche sulla minimappa. Dura $D1.", "Tutti gli attaccanti ottengono $N1 potenza d'attacco a distanza contro questo bersaglio.", 0xf034dbfd, 0x3d2d7958, "uu" },
  [14324] = { "Applica il ⟦Hunter's Mark=Marchio del Cacciatore⟧ al bersaglio, aumentando di $N1 la potenza d'attacco a distanza di tutti gli attaccanti contro quel bersaglio. Inoltre, il bersaglio di questa abilità resta sempre visibile al Cacciatore, anche se diventa furtivo o invisibile. Il bersaglio appare anche sulla minimappa. Dura $D1.", "Tutti gli attaccanti ottengono $N1 potenza d'attacco a distanza contro questo bersaglio.", 0xf034dbfd, 0x3d2d7958, "uu" },
  [14325] = { "Applica il ⟦Hunter's Mark=Marchio del Cacciatore⟧ al bersaglio, aumentando di $N1 la potenza d'attacco a distanza di tutti gli attaccanti contro quel bersaglio. Inoltre, il bersaglio di questa abilità resta sempre visibile al Cacciatore, anche se diventa furtivo o invisibile. Il bersaglio appare anche sulla minimappa. Dura $D1.", "Tutti gli attaccanti ottengono $N1 potenza d'attacco a distanza contro questo bersaglio.", 0xf034dbfd, 0x3d2d7958, "uu" },
  [14326] = { "Spaventa una bestia, costringendola a fuggire per un massimo di $D1. Eventuali danni inflitti al bersaglio potrebbero interrompere l'effetto. Può essere spaventata solo una bestia alla volta.", "Impaurito.", 0xcc6a4f70, 0x5a2205f2, "uu" },
  [14327] = { "Spaventa una bestia, costringendola a fuggire per un massimo di $D1. Eventuali danni inflitti al bersaglio potrebbero interrompere l'effetto. Può essere spaventata solo una bestia alla volta.", "Impaurito.", 0xcc6a4f70, 0x5a2205f2, "uu" },
  [14331] = { "Infligge danni fisici a un nemico ogni $N1 s per $D2.", "Danni fisici inflitti ogni $N1 s.", 0x922b6035, 0xc8fd5ef3, "uu" },
  [14410] = { "+$N1 Intelletto.", nil, 0xd921f4c1, nil, "um" },
  [14507] = { "+$N1 Forza.", nil, 0x7dbddd01, nil, "um" },
  [14514] = { "Ti teletrasporta in avanti di 20 m se non ci sono ostacoli di mezzo. Libera da qualsiasi impedimento.", "In traslazione...", 0xa02ec6f5, 0xe8b15d2f, "uu" },
  [14515] = { "Prende il controllo di un nemico umanoide fino al livello $N1 per $D1.", "Ammaliato.", 0x54466006, 0xd83f67a3, "uu" },
  [14516] = { "Assale un nemico, infliggendo danni in mischia crescenti.", nil, 0xcffda50e, nil, "um" },
  [14517] = { nil, "Danni da sacro subiti aumentati.", nil, 0x6508d97f, "mu" },
  [14518] = { nil, "Danni da sacro subiti aumentati.", nil, 0x6508d97f, "mu" },
  [14520] = { "Riduce il costo in mana di Punizione, ⟦Holy Fire=Fuoco Sacro⟧ e degli incantesimi istantanei del $N1%.", nil, 0x7026d4cd, nil, "um" },
  [14521] = { "Permette al $N1% della rigenerazione del mana di continuare durante il lancio di incantesimi.", nil, 0x86815c0c, nil, "um" },
  [14522] = { "Riduce la durata degli effetti di stordimento, paura e silenzio subiti del $N1%.", nil, 0x3ff087ba, nil, "um" },
  [14523] = { "Riduce la minaccia generata dai tuoi incantesimi del $N1% e la durata degli effetti di stordimento, paura e silenzio subiti del $N2%.", nil, 0x63f081e5, nil, "um" },
  [14524] = { "Aumenta i danni inflitti con le bacchette del $N1%.", nil, 0xf80826f8, nil, "um" },
  [14530] = { "Aumenta la velocità di movimento del $N1% per $D1.", "Velocità di movimento aumentata del $N1%.", 0x61fe647b, 0xdb6814b9, "uu" },
  [14531] = { "Ti conferisce il $N1% di probabilità di ottenere Focused Casting per $D1 dopo aver subito un colpo critico in mischia o a distanza. L'effetto Focused Casting impedisce di perdere tempo di lancio quando subisci danni e aumenta la resistenza agli effetti di interruzione del $N3%.", nil, 0x2eccaa59, nil, "um" },
  [14532] = { "Aumenta i danni fisici subiti dai nemici vicini del $N1% per $D1.", "Danni fisici subiti aumentati del $N1%.", 0x087a6362, 0xed6770df, "uu" },
  [14533] = { "Aumenta i danni da fuoco, da gelo e da arcano subiti dai nemici vicini del $N1% per $D1.", "Danni da fuoco, da gelo e da arcano subiti aumentati del $N1%.", 0xe604a223, 0x294b47dc, "uu" },
  [14534] = { "Aumenta l'intervallo tra gli attacchi dei nemici vicini del $N1% per $D1.", "Intervallo tra gli attacchi aumentato del $N1%.", 0xcfd53330, 0x4f44ab25, "uu" },
  [14535] = { "Riduce gli attributi dei nemici vicini del $N1% per $D1.", "Attributi ridotti del $N1%.", 0xcf0e623a, 0xb4619e26, "uu" },
  [14537] = { "Travolge i nemici frontali con la potenza del vento, del fuoco e di tutta quella roba là!", nil, 0xaab22c2b, nil, "um" },
  [14538] = { "Riduce la velocità di lancio d'incantesimi dei nemici vicini del $N1% per $D1.", "Velocità di lancio d'incantesimi ridotta del $N1%.", 0x89c49e2d, 0x7aa99f75, "uu" },
  [14539] = { "Aumenta i danni da natura subiti dai nemici vicini del $N1% e i danni da ombra del $N2%. Dura $D1.", "Danni da natura subiti aumentati del $N1%.\nDanni da ombra subiti aumentati del $N2%.", 0x5f5cb8a4, 0xd591b4c4, "uu" },
