  [14891] = { "Permette a un minatore di fondere Minerali di ⟦Dark Iron=Ferroscuro⟧ per creare un Lingotto di ⟦Dark Iron=Ferroscuro⟧. Può essere fatto solo alla Forgia Nera nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧.", nil, 0x05e7906e, nil, "um" },
  [14892] = { "Le tue cure critiche non periodiche aumentano l'Armatura del bersaglio del $N1% per $D1.", nil, 0x90cf1ea6, nil, "um" },
