  [14898] = { "Aumenta le cure dei tuoi incantesimi del $N1%.", nil, 0x7dad99a1, nil, "um" },
  [14900] = { "Infonde un alleato ferito d'energia curativa che si propaga agli alleati vicini. L'incantesimo cura fino a un massimo di $N1 bersagli, ma le cure si riducono del 50% a ogni bersaglio successivo.", nil, 0xaf264114, nil, "um" },
  [14901] = { "Aumenta le cure dei tuoi incantesimi fino al $N1% del tuo Spirito totale e i danni dei tuoi incantesimi fino al $N2% del tuo Spirito totale.", nil, 0x58bb1676, nil, "um" },
